CREATE VIEW vw_game_inventory_analysis AS SELECT fgi.GameInventoryKey, dg.GameKey, dg.GameID, dg.GameTitle, dp.PlatformKey, dp.PlatformName, dd.FullDate AS ReleaseDate, dd.CalendarYear AS ReleaseYear, dd.CalendarQuarter AS ReleaseQuarter, dd.CalendarMonthNumber AS ReleaseMonthNumber, dd.CalendarMonthName AS ReleaseMonthName, fgi.GameCount, fgi.FileSizeGB, fge.AcquisitionSourceKey, das.AcquisitionSourceName, fge.AccessStatusKey, dacc.AccessStatusName, fge.OwnedGameCount, fge.StorageLocation, fge.OrganizationFolder, fuga.DifficultyScore, fuga.BaseLengthHours, fuga.CompletionHours, fuga.PersonalRating, fuga.CuratedUserScore FROM FactGameInventory AS fgi INNER JOIN DimGame AS dg ON ((dg.GameKey = fgi.GameKey)) INNER JOIN DimPlatform AS dp ON ((dp.PlatformKey = fgi.PlatformKey)) LEFT JOIN DimDate AS dd ON ((dd.DateKey = fgi.ReleaseDateKey)) LEFT JOIN FactGameEntitlement AS fge ON (((fge.GameKey = fgi.GameKey) AND (fge.PlatformKey = fgi.PlatformKey))) LEFT JOIN DimAcquisitionSource AS das ON ((das.AcquisitionSourceKey = fge.AcquisitionSourceKey)) LEFT JOIN DimAccessStatus AS dacc ON ((dacc.AccessStatusKey = fge.AccessStatusKey)) LEFT JOIN FactUserGameAssessment AS fuga ON ((fuga.GameKey = fgi.GameKey));
